int pqcp_runtime_policy_lookup(
	enum pqcp_runtime_policy_state state,
	enum pqcp_runtime_command_kind command,
	struct pqcp_runtime_policy_decision *decision)
{
	if (state < PQCP_RUNTIME_POLICY_UNINITIALIZED ||
	    state >= PQCP_RUNTIME_POLICY_STATE_COUNT ||
	    command < PQCP_RUNTIME_COMMAND_NONE ||
	    command >= PQCP_RUNTIME_COMMAND_KIND_COUNT ||
	    decision == NULL) {
		return -EINVAL;
	}
	*decision = runtime_catalog[state][command];
	return 0;
}

int pqcp_runtime_policy_catalog_audit(void)
{
	for (size_t state = 0U;
	     state < PQCP_RUNTIME_POLICY_STATE_COUNT; ++state) {
		for (size_t command = 0U;
		     command < PQCP_RUNTIME_POLICY_COMMAND_COUNT;
		     ++command) {
			const struct pqcp_runtime_policy_decision *entry =
				&runtime_catalog[state][command];

			if ((size_t)entry->state != state ||
			    (size_t)entry->command != command ||
			    entry->action >
				PQCP_RUNTIME_POLICY_REQUIRE_RECOVERY ||
			    entry->next_state <
				PQCP_RUNTIME_POLICY_UNINITIALIZED ||
			    entry->next_state >
				PQCP_RUNTIME_POLICY_TERMINATED) {
				return -EBADMSG;
			}
			if (entry->action == PQCP_RUNTIME_POLICY_DENY &&
			    entry->error == 0) {
				return -EBADMSG;
			}
		}
	}
	return 0;
}

